using System.Collections.Generic;

namespace HardlightProject
{
	// Original HLAutoGenerated 0x02000086 (TypeDefIndex 8602); original spelling retained.
	// The .cctor 0x060001bf @0x19F1640 fills the table in native Add order.
	// GetString looks the value up in the live table; a miss is formatted with
	// String.Format("0x{0:X}") on the boxed value and cached through set_Item.
	public static class HardlightEnumExtentions
	{
		private static Dictionary<CharacterStats, string> CharacterStatsEnumToString =
			new Dictionary<CharacterStats, string>(HardlightEnumComparers.CharacterStatsComparer)
			{
				{ CharacterStats.None, "None" },
				{ CharacterStats.Attack, "Attack" },
				{ CharacterStats.AttackAddition, "AttackAddition" },
				{ CharacterStats.AttackBase, "AttackBase" },
				{ CharacterStats.AttackMultiplier, "AttackMultiplier" },
				{ CharacterStats.Defence, "Defence" },
				{ CharacterStats.DefenceAddition, "DefenceAddition" },
				{ CharacterStats.DefenceBase, "DefenceBase" },
				{ CharacterStats.DefenceMultiplier, "DefenceMultiplier" },
				{ CharacterStats.Luck, "Luck" },
				{ CharacterStats.LuckAddition, "LuckAddition" },
				{ CharacterStats.LuckBase, "LuckBase" },
				{ CharacterStats.LuckMultiplier, "LuckMultiplier" },
				{ CharacterStats.Speed, "Speed" },
				{ CharacterStats.SpeedAddition, "SpeedAddition" },
				{ CharacterStats.SpeedBase, "SpeedBase" },
				{ CharacterStats.SpeedMultiplier, "SpeedMultiplier" }
			};

		// 0x060001be @0x19F1520
		public static string GetString(this CharacterStats value)
		{
			string result;
			if (!CharacterStatsEnumToString.TryGetValue(value, out result))
			{
				result = string.Format("0x{0:X}", value);
				CharacterStatsEnumToString[value] = result;
			}
			return result;
		}
	}
}
